import * as THREE from 'three';

import { Configurator } from './';
export class Outer {
	public configurator: Configurator;
	constructor(configurator: Configurator) {
		this.configurator = configurator;
		this.init();
	}
	public init() {
		const geo = new THREE.BoxGeometry(1, 10, 1);
		const material = this.configurator.sceneWrapper.materials.skeletonMaterial;
		const mesh = new THREE.Mesh(geo, material);

		this.configurator.sceneWrapper.scene.add(mesh);
	}
}
