import { APIInterface } from './APIInterface';
import { AppCore } from './AppCore';
import { RendererCore } from './RendererCore';
import { CLICK_TYPE } from './utils/const';
import { View } from './View';

export enum EnvironmentType {
	Playground = 'Playground',
	Configurator = 'Configurator',
	Studio = 'Studio',
	Substation = 'Substation',
	SubstationDiorama = 'Substation Diorama',
	View = 'View',
}

export interface AppHypercube3dInitParams {
	divID: string;

	environmentType?: EnvironmentType;
	ui?: boolean;

	fov?: number;
	webGPU?: boolean;
	performanceMode?: boolean;
	debuggerMode?: boolean;
}

export class AppHypercube3d extends APIInterface {
	static async init({ divID, ui = false, webGPU = false, performanceMode = false, debuggerMode = false, fov, environmentType }: AppHypercube3dInitParams) {
		const app = new AppHypercube3d({ divID, ui, webGPU, performanceMode, debuggerMode, environmentType });
		await app.init();
		if (fov) app.appCore.common.changeFOV(fov);
		return app;
	}

	public RendererCore!: RendererCore;
	public appCore!: AppCore;
	public view: View | undefined = undefined;
	public id: string;

	public navigationScene: boolean;
	public isPerformanceMode: boolean;
	public webGPU: boolean = false;
	public debuggerMode: boolean = false;
	public debuggerUI: boolean = false;
	public environmentType: EnvironmentType;

	constructor({ divID = 'main', ui = true, webGPU = false, performanceMode = false, debuggerMode = false, environmentType }: AppHypercube3dInitParams) {
		super();
		const params = new URLSearchParams(window.location.search);

		this.navigationScene = params.get('sc') === '1';

		this.isPerformanceMode = params.get('performance') === 'true' || performanceMode;

		this.id = divID;
		this.webGPU = webGPU;
		this.debuggerMode = debuggerMode;
		this.debuggerUI = ui;
		this.environmentType = environmentType;
	}
	public async init() {
		await this.initRenderer();
		if (this.debuggerMode && this.debuggerUI) await this.initView();
		await this.initApp();

		this.bindEvent();
		this.bindRenderer();
	}
	private async initRenderer() {
		this.RendererCore = new RendererCore(this.id, this.isPerformanceMode);
		this.RendererCore.useWebGPU = this.webGPU;
		this.RendererCore.debuggerMode = this.debuggerMode;
		await this.RendererCore.init();
	}
	private async initView() {
		this.view = new View(this);
		await this.view.init();
	}
	private async initApp() {
		this.appCore = new AppCore(this, this.isPerformanceMode, this.navigationScene);
		await this.appCore.init();
	}

	public bindEvent() {
		this.RendererCore.onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => this.appCore.onMouseEventListener(e, type);
	}
	public bindRenderer() {
		this.RendererCore.update = () => this.appCore.update();
	}
	public destroy() {
		this.RendererCore?.destroy();
		this.view?.destroy();
		this.appCore?.destroy();
	}
}
