import * as THREE from 'three';
import { MeshWrapperCommon } from '../base/MeshWrapperCommon';
import { SUBTRACTION, Brush, Evaluator } from 'three-bvh-csg';
import { SceneWrapper } from '../';
import { createStudioEnvironment, getSubtractionMesh } from '../../../utils/ThreeUtils';

import { Outer } from './Outer';
import { Dimension } from './Dimension';

export class Configurator extends MeshWrapperCommon {
	meshSphere: THREE.Mesh;
	public value = 0;
	globalClippingPlane: THREE.Plane;
	resultMesh: THREE.Mesh | null = null;

	dimension: Dimension = new Dimension();
	outer: Outer;

	constructor(sceneWrapper: SceneWrapper) {
		super(sceneWrapper);
		this.init();
	}

	public init() {
		this.outer = new Outer(this);

		// Create environment mesh
		this.meshSphere = createStudioEnvironment();
		this.meshSphere.castShadow = false;
		this.meshSphere.receiveShadow = false;
		this.sceneWrapper.scene.add(this.meshSphere);

		// Define clipping plane
		this.globalClippingPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), this.value);

		// Material creation
		const material = new THREE.MeshPhysicalMaterial({
			color: 0x444444,
			roughness: 0.2,
			metalness: 0.1,
			normalMap: this.sceneWrapper.appCore.isPerformanceMode ? null : this.sceneWrapper.materials.normalMap,
			clippingPlanes: [this.globalClippingPlane],
			clipShadows: true,
			side: THREE.DoubleSide,

			stencilWrite: true,
			stencilFunc: THREE.AlwaysStencilFunc,
			stencilRef: 1,
			stencilZPass: THREE.ReplaceStencilOp,
		});
		// @ts-ignore
		material.onBeforeCompile = (shader: THREE.Shader) => {
			shader.uniforms.clippedSectionColor = { value: new THREE.Vector3(1, 0, 0) };
			shader.fragmentShader =
				`
				uniform vec3 clippedSectionColor;
				` + shader.fragmentShader;

			shader.fragmentShader = shader.fragmentShader.replace(
				'#include <opaque_fragment>',
				`
				if (gl_FrontFacing == false) {
				outgoingLight = clippedSectionColor; // Set clipped section to black
				}
				#include <opaque_fragment>
				`
			);

			// console.log('Modified Fragment Shader:', shader.fragmentShader);
		};

		// // Create brushes with the material
		// const brush1 = new Brush(new THREE.BoxGeometry(1, 1, 1), material);
		// brush1.updateMatrixWorld();

		// const brush2 = new Brush(new THREE.SphereGeometry(1, 32, 32), material);
		// brush2.position.set(0.5, 0.5, 0.5);
		// brush2.updateMatrixWorld();

		// // Perform CSG subtraction
		// const evaluator = new Evaluator();
		// this.resultMesh = evaluator.evaluate(brush1, brush2, SUBTRACTION);

		this.resultMesh = getSubtractionMesh(new THREE.BoxGeometry(2, 2, 2), new THREE.SphereGeometry(2, 32, 32), material);

		// Store original raycast method
		const originalRaycast = THREE.Mesh.prototype.raycast;

		// Custom raycasting to ignore clipped sections
		this.resultMesh.raycast = (raycaster: THREE.Raycaster, intersects: THREE.Intersection[]) => {
			console.log('Raycast called'); // Debug

			// Perform original raycast
			const tempIntersects: THREE.Intersection[] = [];
			originalRaycast.call(this.resultMesh, raycaster, tempIntersects);

			// Filter out intersections beyond the clipping plane
			for (const intersect of tempIntersects) {
				const point = intersect.point;
				const distance = this.globalClippingPlane.distanceToPoint(point);
				console.log('Intersection point:', point, 'Distance:', distance); // Debug
				if (distance >= 0) {
					intersects.push(intersect);
					console.log('Valid intersection added'); // Debug
				} else {
					console.log('Clipped intersection ignored'); // Debug
				}
			}
		};

		// Add result to scene
		this.sceneWrapper.scene.add(this.resultMesh);

		this.ready = true;
	}

	public updateClipping(value: number) {
		this.globalClippingPlane.constant = value;
	}

	public add(): void {
		this.sceneWrapper.add(this);
	}

	public update(): boolean {
		return false;
	}

	public show(value: boolean) {
		// TODO
	}
}
